-- Demo restaurant: dish photos (app/public/demo/dishes/, AI-generated by the owner), copied into
-- the dish-images bucket by the edge function seed-demo-branding. 1200 px photo + 400 px thumbnail,
-- the same sizes the app makes when an owner uploads one.
update public.menu_items i
set image_path = r.id::text || '/' || i.id::text || '/stoofvlees.jpg',
    image_thumb_path = r.id::text || '/' || i.id::text || '/stoofvlees_thumb.jpg'
from public.restaurants r
where r.id = i.restaurant_id and r.slug = 'demo' and i.name = 'Stoofvlees met frietjes';
